import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        // The best subarray can always be shrunk to two adjacent elements.
        long best = 0;
        for (int i = 0; i + 1 < n; i++) best = Math.max(best, a[i] + a[i + 1]);
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// The best subarray can always be shrunk to two adjacent elements.
	best := 0
	for i := 0; i+1 < n; i++ {
		best = max(best, a[i]+a[i+1])
	}
	fmt.Println(best)
}
